import{_ as i,l as o,o as e,c as n,v as t,p as s,x as r,d as A,i as C,S as P}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"APIC 与中断路由","description":"","frontmatter":{"title":"APIC 与中断路由","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/apic-interrupt-routing.md","filePath":"cs/apic-interrupt-routing.md","lastUpdated":1789023840000}'),l={name:"cs/apic-interrupt-routing.md"};function p(c,a,d,h,E,u){const I=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="apic-与中断路由" tabindex="-1">APIC 与中断路由 <a class="header-anchor" href="#apic-与中断路由" aria-label="Permalink to &quot;APIC 与中断路由&quot;">​</a></h1><div class="epigraph"><p>每颗核有本地 APIC，I/O APIC 或消息窗口把向量送到选定的 APIC ID；路由决定哪颗 CPU 跑处理函数，而不是设备再拉一根线到那颗核。</p><footer>—— 据 Intel 64 and IA-32 Architectures Software Developer’s Manual；Patterson and Hennessy, Computer Organization and Design 整理</footer></div><p><a href="/cs/msi-msix">上一课</a>把设备中断变成写消息。RISC-V 教学用 <a href="/cs/plic-irq">PLIC</a>。x86 世界缺口是 <strong>APIC 体系</strong>：Local APIC、I/O APIC、x2APIC MSR，以及如何把 MSI 地址里的目标变成某核的向量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>8259 PIC 只够单核。APIC：每个处理器一个本地单元（定时器、IPI、接收中断），I/O APIC 连遗留线。MSI 地址编码目标 APIC ID 与投递模式（固定、最低优先级）。缺口不是 MSI 表格式，而是<strong>路由策略</strong>：绑定到一核 vs 分散，与 OS 的 irq affinity 同一对象。</p><p>IPI：核间中断，用于 TLB shootdown、停机，不是 PCIe 设备发出的。本课点名，机制同本地 APIC 接收。</p><h3 id="apic-不是「另一套-pcie-根复合体」" tabindex="-1">APIC 不是「另一套 PCIe 根复合体」 <a class="header-anchor" href="#apic-不是「另一套-pcie-根复合体」" aria-label="Permalink to &quot;APIC 不是「另一套 PCIe 根复合体」&quot;">​</a></h3><p>它是中断控制器，配置曾走 MMIO（APIC 基址），x2APIC 改 MSR。不参与 BAR 枚举（除了作为 MSI 写的目标）。把 APIC 当端点设备扫 Vendor ID，枚举代码会迷路。</p><p><span class="marginnote">Intel SDM 卷 3 是 APIC 主文献。AMD 有兼容实现。ARM GIC 是平行设计，后课 AArch64 点到即可，本课以 APIC 钉 x86 主机侧。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>OS 初始化本地 APIC、写 TPR、校准 APIC 定时器（下一课定时器家族）。对 MSI-X：填写目标 APIC ID。最低优先级投递依赖仲裁，现代 OS 多用固定亲和。虚拟化：APIC 虚拟化减少 VM-exit，本课不展开。</p>',11)),(e(),s(P,null,{default:r(()=>[C(I,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MSI%5B%22MSI%20%E5%86%99%22%5D%20--%3E%20ROUTE%5B%22%E6%8C%89%20APIC%20ID%20%E8%B7%AF%E7%94%B1%22%5D%0A%20%20IOA%5B%22I%2FO%20APIC%20%E9%81%97%E7%95%99%E7%BA%BF%22%5D%20--%3E%20ROUTE%0A%20%20IPI%5B%22%E6%A0%B8%E9%97%B4%20IPI%22%5D%20--%3E%20LAPIC%5B%22%E6%9C%AC%E5%9C%B0%20APIC%22%5D%0A%20%20ROUTE%20--%3E%20LAPIC%0A%20%20LAPIC%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%AE%9A%E6%97%B6%E5%99%A8%E4%B9%9F%E5%9C%A8%E6%9C%AC%E5%9C%B0%20APIC%20%E4%B8%8A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>RISC-V 平台若用 IMSIC，每 hart 入队 MSI，思想同「每核接收器」，寄存器不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>定时器、热插拔 CPU、电源状态都会改「谁能收中断」。DMA 与中断的配对：数据 DMA 完成对主机内存可见后才发 MSI，否则处理函数读到旧描述符——围栏与 PCIe 序，下一课 DMA 展开。本课先把向量送到核。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列全部投递模式比特，不写 PIC 级联历史作业。不把 GIC 寄存器表抄满。不进入中断延迟的实时操作系统全书。</p><p>后课默认：x86 上 MSI 目标是 APIC 路由到 Local APIC；IPI 走同一接收器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Local APIC 每核接收；I/O APIC 收遗留线。</li><li>MSI 地址携带 APIC ID；OS 决定亲和。</li><li>IPI 是核间，不是 PCIe 设备。</li><li>出处：Intel SDM；Patterson and Hennessy, COD；PLIC 对照。</li></ul>',8))])}const m=i(l,[["render",p]]);export{_ as __pageData,m as default};
